mapper.select:
	SELECT 
  	REPORTTYPE AS reportType,
  	PROPERTYCODE AS propertyCode, 
 	BALANCE AS balance
	FROM CHB_MONTH_REPORT_DETAIL DETAIL
	WHERE DETAIL.REPORTUUID = (SELECT REPORTUUID FROM (
		SELECT ROW_NUMBER() OVER(PARTITION BY T.TERMID ORDER BY T.UPDATE_TIME DESC) RN,       
        	T.REPORTUUID,
        	T.TERMID
        	FROM CHB_MONTH_REPORT T

			where  T.org_code=#{org, jdbcType=VARCHAR}

		)A WHERE A.RN = 1 AND A.TERMID = #{termId, jdbcType=VARCHAR}
  	)

SELECT
REPORTTYPE AS reportType,
PROPERTYCODE AS propertyCode,
BOTTOMBALANCE AS balance
FROM CHB_MONTH_REPORT_DETAIL DETAIL
WHERE DETAIL.REPORTUUID = (SELECT REPORTUUID FROM (
SELECT ROW_NUMBER() OVER(PARTITION BY T.TERMID ORDER BY T.UPDATE_TIME DESC) RN,
T.REPORTUUID,
T.TERMID
FROM CHB_MONTH_REPORT T

	where  T.org_code=#{org, jdbcType=VARCHAR}

) T1 WHERE RN = 1 AND TERMID = #{termId, jdbcType=VARCHAR}
)

SELECT A.VALCODE, sum(ifnull(ASSETVALUE_A,0)) valueA, sum(ifnull(ASSETVALUE_B,0)) valueB, sum(ifnull(VALUEA_LAST,0)) valueALast, sum(ifnull(VALUEB_LAST,0)) valueBLast, (case sum(ifnull(ASSETVALUE_A, 0)) when 0 then 0 else SUM(avgRate1) / sum(ifnull(ASSETVALUE_A, 0)) end) avgRate1, (case sum(ifnull(ASSETVALUE_B, 0)) when 0 then 0 else SUM(avgRate2) / sum(ifnull(ASSETVALUE_B, 0)) end) avgRate2, (case sum(ifnull(VALUEA_LAST, 0)) when 0 then 0 else SUM(avgRate1Last) / sum(ifnull(VALUEA_LAST, 0)) end) avgRate1Last, (case sum(ifnull(VALUEB_LAST, 0)) when 0 then 0 else SUM(avgRate2Last) / sum(ifnull(VALUEB_LAST, 0)) end) avgRate2Last, MAX(heaverTimes1) heaverTimes1, MAX(heaverTimes2) heaverTimes2, sum(valueB01) valueB01, sum(valueBlast01) valueBlast01, sum(valueB02) valueB02, sum(valueBlast02) valueBlast02 FROM ( SELECT CONCAT(CONCAT(CONCAT(CONCAT(AI.CONSTRACTE_BUSI_TYPE,'_'),AI.CONSTRACTE_GRADE),'_'),(case AI.ASSET_TYPE2 when '1116' then 'F01' else 'F06' end ))VALCODE, POS.ASSETVALUE_A, POS.ASSETVALUE_B, POS1.ASSETVALUE_A VALUEA_LAST, POS1.ASSETVALUE_B VALUEB_LAST, ifnull(POS.ASSETVALUE_A,0)*ifnull(AI.CONSTRACTE_HEAVER_TIMES,0) avgRate1, ifnull(POS.ASSETVALUE_B,0)*ifnull(AI.CONSTRACTE_HEAVER_TIMES,0) avgRate2, ifnull(POS1.ASSETVALUE_A,0)*ifnull(AI.CONSTRACTE_HEAVER_TIMES,0) avgRate1Last, ifnull(POS1.ASSETVALUE_B,0)*ifnull(AI.CONSTRACTE_HEAVER_TIMES,0) avgRate2Last, CASE WHEN POS.ASSET_CODE IS NOT NULL THEN AI.CONSTRACTE_HEAVER_TIMES ELSE 0 END heaverTimes1, CASE WHEN POS1.ASSET_CODE IS NOT NULL THEN AI.CONSTRACTE_HEAVER_TIMES ELSE 0 END heaverTimes2, (case AI.CHB_SECTYPE when '22' then ifnull(POS.ASSETVALUE_B,0) else 0 end) valueB01, (case AI.CHB_SECTYPE when '22' then ifnull(POS1.ASSETVALUE_B,0) else 0 end) valueBlast01, (case AI.CHB_SECTYPE when '23' then ifnull(POS.ASSETVALUE_B,0) else 0 end) valueB02, (case AI.CHB_SECTYPE when '23' then ifnull(POS1.ASSETVALUE_B,0) else 0 end) valueBlast02 FROM CHB_ASSET_INFO AI LEFT JOIN CHB_MONTH_ASSET_POSITION POS ON AI.ASSET_CODE = POS.ASSET_CODE and DATE_FORMAT(pos.enddate,'%Y-%m')= #{termId, jdbcType=VARCHAR} LEFT JOIN CHB_MONTH_ASSET_POSITION POS1 ON AI.ASSET_CODE = POS1.ASSET_CODE and DATE_FORMAT(pos1.enddate,'%Y-%m')= #{lastTermId, jdbcType=VARCHAR}
left join DATA_AUTH_NOTIFY_INST di on POS.PROD_ID=di.business_id and di.model_type = '02' AND DI.DATA_TYPE= 'PTL01'
WHERE AI.STATUS IN ('E','M') and AI.ASSET_TYPE2 IN ('1116','2299','1201','1210','1202','1203','1204','1205','1206','1207','1208','1209','1211','1212','1213','2202' ,'1299','1301','1399','2101','2617') and (POS.ASSET_CODE is not null or POS1.ASSET_CODE is not null
and di.institution_code=#{org, jdbcType=VARCHAR}
) ) A GROUP BY A.VALCODE
